442: 		sMorphTime = sTime;
443: 
444: 		pImage->SetColor( NGfx::SPixel8888( 0xFF, 0xFF, 0xFF, 0xFF * fCoeff ) );
445: 		pImage->Draw( this, sTime, pView );
446: 	}
